// ── Product: immutable HTTP Request ─────────────────────────────
class HttpRequest {
  constructor({ url, method, headers, body, timeout, retries, auth }) {
    if (!url)    throw new Error('url is required');
    if (!method) throw new Error('method is required');
    this.url     = url;
    this.method  = method.toUpperCase();
    this.headers = Object.freeze({ ...headers });
    this.body    = body    ?? null;
    this.timeout = timeout ?? 5000;
    this.retries = retries ?? 0;
    this.auth    = auth    ?? null;
    Object.freeze(this);
  }

  toString() {
    return `[${this.method}] ${this.url} (timeout:${this.timeout}ms retries:${this.retries})`;
  }
}

// ── Builder ───────────────────────────────────────────────────────
class HttpRequestBuilder {
  #config;

  constructor(url) {
    this.#config = {
      url,
      method:  'GET',
      headers: {},
      body:    null,
      timeout: 5000,
      retries: 0,
      auth:    null,
    };
  }

  method(method)         { this.#config.method  = method;  return this; }
  header(key, value)     { this.#config.headers[key] = value; return this; }
  body(body)             { this.#config.body    = body;    return this; }
  timeout(ms)            { this.#config.timeout = ms;      return this; }
  retry(count)           { this.#config.retries = count;   return this; }
  bearerAuth(token)      { this.#config.auth = `Bearer ${token}`; return this; }
  contentType(type)      { return this.header('Content-Type', type); }

  build() {
    // Cross-field validation
    if (this.#config.body && this.#config.method === 'GET') {
      throw new Error('GET requests cannot have a body');
    }
    if (this.#config.timeout < 0) {
      throw new Error('timeout must be a positive number');
    }
    return new HttpRequest(this.#config);
  }
}

// ── Director: encodes common presets ────────────────────────────
class HttpRequestDirector {
  #builder;
  constructor(builder) { this.#builder = builder; }

  buildAuthenticatedPost(body, token) {
    return this.#builder
      .method('POST')
      .contentType('application/json')
      .body(JSON.stringify(body))
      .bearerAuth(token)
      .timeout(10000)
      .retry(3)
      .build();
  }

  buildHealthCheck() {
    return this.#builder
      .method('GET')
      .timeout(2000)
      .retry(1)
      .build();
  }
}

// ── Direct builder usage (fluent chain) ──────────────────────────
const getRequest = new HttpRequestBuilder('https://api.example.com/users')
  .method('GET')
  .header('Accept', 'application/json')
  .timeout(3000)
  .build();

console.log(getRequest.toString());
// [GET] https://api.example.com/users (timeout:3000ms retries:0)

// ── Director usage (preset recipe) ──────────────────────────────
const postBuilder = new HttpRequestBuilder('https://api.example.com/orders');
const director   = new HttpRequestDirector(postBuilder);
const authPost   = director.buildAuthenticatedPost({ item: 'book', qty: 2 }, 'tok_abc');

console.log(authPost.toString());
// [POST] https://api.example.com/orders (timeout:10000ms retries:3)
console.log(authPost.headers['Content-Type']); // application/json
console.log(authPost.auth);                    // Bearer tok_abc

// ── Validation in build() ────────────────────────────────────────
try {
  new HttpRequestBuilder('https://api.example.com/data')
    .method('GET')
    .body('bad idea')
    .build();
} catch (e) {
  console.log(e.message); // GET requests cannot have a body
}

// ── Builder: structural skeleton ────────────────────────────────

// Product — immutable, all fields set in constructor
class Product {
  constructor(config) {
    this.a = config.a;
    this.b = config.b ?? 'default';
    this.c = config.c ?? 0;
    Object.freeze(this);
  }
}

// Builder — accumulates config, produces Product on build()
class ProductBuilder {
  #c = {};

  setA(value) { this.#c.a = value; return this; }  // returns this for chaining
  setB(value) { this.#c.b = value; return this; }
  setC(value) { this.#c.c = value; return this; }

  build() {
    if (this.#c.a === undefined) throw new Error('a is required');
    return new Product(this.#c);
  }
}

// Director — optional; encodes reusable recipes
class Director {
  constructor(builder) { this._b = builder; }

  buildMinimal(a) {
    return this._b.setA(a).build();
  }

  buildFull(a, b, c) {
    return this._b.setA(a).setB(b).setC(c).build();
  }
}

// Usage — direct chaining
const p1 = new ProductBuilder().setA('hello').setB('world').setC(42).build();
console.log(p1); // Product { a: 'hello', b: 'world', c: 42 }

// Usage — via Director
const dir = new Director(new ProductBuilder());
const p2 = dir.buildFull('x', 'y', 7);
console.log(p2); // Product { a: 'x', b: 'y', c: 7 }

// ── Telescoping constructor (the anti-pattern this replaces) ─────
// AVOID: new Product('hello', null, null, null, true, null, 42, null)
// PREFER: new ProductBuilder().setA('hello').setC(42).build()
